--
-- Food safety dashboard sample data for components 306, 307, 501, 502, 503, and 505.
-- Included by dashboard-demo.sql during dashboard data DB initialization.
--

BEGIN;

CREATE EXTENSION IF NOT EXISTS postgis WITH SCHEMA public;

DROP TABLE IF EXISTS public.water_quality_tpe;
DROP TABLE IF EXISTS public.water_quality_ntpe;
DROP TABLE IF EXISTS public.food_source_tpe;
DROP TABLE IF EXISTS public.food_source_ntpe;
DROP TABLE IF EXISTS public.food_audit_violation_tpe;
DROP TABLE IF EXISTS public.food_audit_violation_ntpe;
DROP TABLE IF EXISTS public.health_audit_violation_tpe;
DROP TABLE IF EXISTS public.health_audit_violation_ntpe;
DROP TABLE IF EXISTS public.post_help_agency_tpe;
DROP TABLE IF EXISTS public.post_help_agency_ntpe;
DROP TABLE IF EXISTS public.fda_good_restaurants;
DROP TABLE IF EXISTS public.cdc_infectious_disease;
DROP TABLE IF EXISTS public.food_safety_death_cause_share;

CREATE TABLE public.water_quality_tpe (
    ogc_fid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    etl_update_time timestamp without time zone,
    source_row_no integer,
    name text,
    english_name text,
    city text,
    district text,
    address text,
    water_sources text,
    data_time text,
    qualified text,
    ph double precision,
    turbidity_ntu double precision,
    free_residual_chlorine_mg_l double precision,
    total_hardness_mg_l double precision,
    total_dissolved_solids_mg_l double precision,
    coliform_cfu_100ml text,
    source_dataset text,
    source_url text,
    location_method text,
    lng double precision,
    lat double precision,
    wkb_geometry public.geometry(Point, 4326)
);

CREATE TABLE public.water_quality_ntpe (
    ogc_fid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    etl_update_time timestamp without time zone,
    source_row_no integer,
    name text,
    english_name text,
    city text,
    district text,
    address text,
    water_sources text,
    data_time text,
    qualified text,
    ph double precision,
    turbidity_ntu double precision,
    free_residual_chlorine_mg_l double precision,
    total_hardness_mg_l double precision,
    total_dissolved_solids_mg_l double precision,
    coliform_cfu_100ml text,
    source_dataset text,
    source_url text,
    location_method text,
    lng double precision,
    lat double precision,
    wkb_geometry public.geometry(Point, 4326)
);

