CREATE TABLE public.food_source_tpe (
    district text
);

CREATE TABLE public.food_source_ntpe (
    district text
);

CREATE TABLE public.food_audit_violation_tpe (
    district text
);

CREATE TABLE public.food_audit_violation_ntpe (
    district text
);

CREATE TABLE public.health_audit_violation_tpe (
    district text
);

CREATE TABLE public.health_audit_violation_ntpe (
    district text
);

CREATE TABLE public.post_help_agency_tpe (
    agency_type text
);

CREATE TABLE public.post_help_agency_ntpe (
    agency_type text
);

CREATE TABLE public.fda_good_restaurants (
    data_time timestamp with time zone,
    city character varying(20),
    district character varying(20),
    award_year integer,
    restaurant_name text,
    address text,
    lng double precision,
    lat double precision,
    rating_result character varying(10),
    wkb_geometry text
);

CREATE TABLE public.cdc_infectious_disease (
    data_time timestamp with time zone,
    year integer,
    week integer,
    dataset_name text,
    surveillance_type text,
    disease_group text,
    disease_name text,
    visit_type text,
    age_group text,
    county text,
    county_code integer,
    patient_visit integer,
    total_nhi_patient_visit integer,
    diarrhea_visit_rate double precision
);

CREATE TABLE public.food_safety_death_cause_share (
    data_time timestamp with time zone,
    year integer,
    city text,
    death_cause text,
    metric_basis text,
    cause_value double precision,
    all_cause_value double precision,
    death_share_percent double precision
);

